INSERT INTO `customer_loans` (`id`,`companyId`,`creditManager`,`accountNumber`,`amount`,`numberOfInstallments`,`interestRate`,`loanDescription`,`dateCreated`,`status`,`createdAt`,`updatedAt`,`capacityExcessObservation`,`borrowerInfo`,`administrativeFee`,`disbursementDate`,`customerId`,`rate_type`,`rate_type_label`,`walletId`) VALUES
(61,36,353,100,"100000.00",18,"0.0200","Conforme análise documental e declaração de rendimentos, a margem de lucro mensal apurada é de 50.640,00 MT, e acreditamos que com o valor solicitado, e por sabermos que o cliente dispõe de outros rendimentos não declarados (referentes ao seu salário), o negócio  poderá gerar um lucro superior em relação ao que gera actualmente sem nenhum empréstimo.","2026-09-02","1","2026-09-02 11:25:12","2026-09-14 11:50:41",NULL,"{\"finalidade\":\"Comercio\",\"garantia\":\"Ema mercearia localizada no bairro de mutiticoma, perto do Frank. (190 000,00 MT)\",\"seguroVida\":\"Sim\",\"capitalSeguro\":\"100 000,00 MT\",\"seguroBem\":\"Não\",\"beneficiario\":\"MBR Microcrédito até ao saldo devedor\"}","0.00","2026-09-03",328,"MENSAL",NULL,NULL),
(62,36,353,101,"90000.00",18,"0.0900","As garantias oferecidas são sólidas e parecem superar o valor do crédito. A propria loja comercial, objecto de investimento, e imóvel residencial, ambos com documentação regular.","2026-09-02","1","2026-09-02 11:25:12","2026-09-14 11:51:10","Conforme análise documental e declaração de rendimentos, a margem de lucro mensal apurada é de 29.000,00 MT, e acreditamos que com o valor solicitado, o negócio  poderá gerar um lucro superior em relação ao que gera actualmente sem nenhum empréstimo.","{\"finalidade\":\"Comercio\",\"garantia\":\"A loja comercial feita a blocos (mercearia) (2,00 MT), Uma residência tipo 2, localizada em Larde, no bairro de Maganha perto do rio Maganha (200 000,00 MT)\",\"seguroVida\":\"Sim\",\"capitalSeguro\":\"90 000,00 MT\",\"seguroBem\":\"Não\",\"beneficiario\":\"MBR Microcrédito até ao saldo devedor\"}","0.00","2026-09-03",329,"MENSAL",NULL,NULL),
(63,36,353,102,"20000.00",18,"0.0200","Proponente com experieência operacional validada. Já actua no mercado, reduzindo o risco de implementaçã do negócio. Cartela de clientes garantida, demanda já existente.","2026-09-02","1","2026-09-02 11:25:12","2026-09-14 11:51:35",NULL,"{\"finalidade\":\"Comercio\",\"garantia\":\"A sua residencia feita de material precario (30 000,00 MT)\",\"seguroVida\":\"Sim\",\"capitalSeguro\":\"20 000,00 MT\",\"seguroBem\":\"Não\",\"beneficiario\":\"MBR Microcrédito até ao saldo devedor\"}","0.00","2026-09-03",330,"MENSAL",NULL,NULL),
(66,36,353,105,"300000.00",18,"0.0200","É um cliente com uma certa experiência no ramo que pretende investir, visto que trabalha com o mesmo negócio há um tempo.","2026-09-02","1","2026-09-02 11:25:12","2026-09-14 11:52:03","Conclui-se pela viabilidade financeira, o baixo risco da operação, tendo em conta o crédito solicitado. O cliente demonstra comprometimento com o projeto e coloca como garantia um carro Toyota Alphard, AML 485 MC, na cor branca.","{\"finalidade\":\"Talho\",\"garantia\":\"Um carro Toyota Alphard, AML 485 MC, na cor branca (900 000,00 MT)\",\"seguroVida\":\"Sim\",\"capitalSeguro\":\"300 000,00 MT\",\"seguroBem\":\"Não\",\"beneficiario\":\"MBR Microcrédito até ao saldo devedor\"}","0.00","2026-09-03",333,"MENSAL",NULL,NULL),
(67,36,353,106,"150000.00",18,"0.0200","Aprovamos o credito de 150.000,00 MT ao sr Saide Ali Fargi considerando a consistencia que o negocio apresenta, o rendimento mensal e de 40.350,00 MT.","2026-09-02","1","2026-09-02 11:25:12","2026-09-14 11:53:43",NULL,"{\"finalidade\":\"Comercio\",\"garantia\":\"Uma mercearia localizada no bairro de Tipane (130 000,00 MT)\",\"seguroVida\":\"Sim\",\"capitalSeguro\":\"150 000,00 MT\",\"seguroBem\":\"Não\",\"beneficiario\":\"MBR Microcrédito até ao saldo devedor\"}","0.00","2026-09-03",334,"MENSAL",NULL,NULL),
(68,36,353,107,"350000.00",18,"0.0200","Conforme a nossa análise trata-se de um investimento em expansão de atividade já rentável e consolidada. Conclui-se pela viabilidade financeira e baixo risco da operação tendo em conta o crédito solicitado.Trata-se de um cliente com perfil investidor, que já dispõe de capital inicial próprio para aquisição do veículo destinado a atividade de transporte. Esta estrutura reduz significativamente o risco da operação, pois demonstra comprometimento do cliente com o projeto e entrada imediata do bem como garantia real.","2026-09-02","0","2026-09-02 11:25:12","2026-09-14 11:45:52","De acordo com a análise de viabilidade do projeto, considera-se que o plano de negócio apresentado por este cliente é consistente e o empreendimento tem capacidade de gerar fluxo de caixa suficiente para honrar as prestações dentro do prazo contratado. O cliente apresenta capacidade de faturamento que varia de 60.000,00 MT a 75.000,00 MT mensalmente dependendo do fluxo do trabalho. A finalidade deste crédito é de investir na compra de uma viatura para exercer as actividades de transporte de passageiros e mercadorias. A viatura consiste numa das garantias apresentadas. O risco é baixo visto que é um cliente experiente na área que pretende trabalhar.","{\"finalidade\":\"Transporte de Carga e de passageiros\",\"garantia\":\"A parte frontal de uma casa tipo 2, com dois quartos e sala, 1 cozinha, casa de banho interna e uma varanda. (900 000,00 MT)\",\"seguroVida\":\"Sim\",\"capitalSeguro\":\"350 000,00 MT\",\"seguroBem\":\"Não\",\"beneficiario\":\"MBR Microcrédito até ao saldo devedor\"}","0.00",NULL,335,"MENSAL",NULL,NULL),
