-- ---------- accounts ----------
DROP TABLE IF EXISTS `accounts`;
CREATE TABLE `accounts` (
  `id` int NOT NULL AUTO_INCREMENT,
  `companyId` int NOT NULL,
  `accountNumber` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `accountDescription` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `bank_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `bank_code` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `balance` decimal(15,2) NOT NULL DEFAULT '0.00',
  `initial_balance` decimal(15,2) DEFAULT '0.00',
  `purpose` enum('REEMBOLSO','DESEMBOLSO','MISTO','TAXAS','RESERVA') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MISTO',
  `type` enum('BANCO','CAIXA_FISICO','MOBILE_MONEY','EWALLET') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'BANCO',
  `is_default_reembolso` tinyint(1) NOT NULL DEFAULT '0',
  `is_default_desembolso` tinyint(1) NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `currency` varchar(3) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'MZN',
  `accountHolder` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `createdBy` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `updatedBy` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_accounts_company_number` (`companyId`,`accountNumber`),
  KEY `idx_company_purpose_active` (`companyId`,`purpose`,`is_active`),
  CONSTRAINT `fk_accounts_company` FOREIGN KEY (`companyId`) REFERENCES `companies` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------- amortization_loans ----------
DROP TABLE IF EXISTS `amortization_loans`;
CREATE TABLE `amortization_loans` (
  `id` int NOT NULL AUTO_INCREMENT,
  `companyId` int NOT NULL,
  `loanId` int NOT NULL,
  `installmentOrder` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `accountNumber` int NOT NULL,
  `amortization` decimal(15,2) NOT NULL,
  `rateAmount` decimal(15,2) NOT NULL,
  `installment` decimal(15,2) NOT NULL,
  `dueDate` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `status` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `remainingBalance` decimal(15,2) DEFAULT NULL,
  `paidAmount` decimal(15,2) DEFAULT '0.00',
  `customerId` int DEFAULT NULL,
  `walletId` int DEFAULT NULL,
  `mora_amount` decimal(15,2) NOT NULL DEFAULT '0.00',
  `mora_days` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_amortization_loan` (`loanId`),
  KEY `fk_amortization_customer` (`customerId`),
  KEY `idx_amortization_walletId` (`walletId`),
  CONSTRAINT `fk_amortization_customer` FOREIGN KEY (`customerId`) REFERENCES `customers` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_amortization_loan` FOREIGN KEY (`loanId`) REFERENCES `customer_loans` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_amortization_wallet` FOREIGN KEY (`walletId`) REFERENCES `financing_wallets` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=900 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------- bank_transactions ----------
